import { useEffect, useRef, useState } from "react";
import { Check, Share2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { BarkPillButton } from "@/components/ui/BarkPillButton";
import { cn } from "@/lib/utils";
import { hapticLight } from "@/lib/haptics";
import { shareNative } from "@/lib/nativeShare";
import { isNativePlatform } from "@/lib/nativeInit";

interface ShareJobButtonProps {
  /** The job being shared — only the title/budget/category/id/city are referenced. */
  job: {
    id: string;
    title: string;
    budget?: number;
    category?: string;
    /** City string (no state suffix) shown in the share text. */
    city?: string;
  };
  /**
   * Optional className passthrough so the host action row can size and
   * tint the button consistently with its siblings (Edit/Cancel, Save,
   * etc.). Keep host styling outside the component so each mount can
   * match its row.
   */
  className?: string;
  /**
   * Render mode — defaults to a full pill-style button (label + icon)
   * suitable for the customer-side action row beside Edit / Cancel.
   * Use `"icon"` for icon-only mounts like the helper-side dialog
   * footer where the row is a sequence of equal-square icon buttons.
   *
   * `"primary"` is the GLOSSY bark pill — for the one mount where sharing is
   * the screen's single primary action (the Applicants empty state), not one
   * option in a row of peers. It renders through `BarkPillButton`, the same
   * component every other empty-state CTA in the app uses, so there is exactly
   * one implementation of that treatment. The `default` mount stays a flat
   * tint on purpose: in an action row beside Edit / Cancel a glossy Share
   * would claim a primacy it does not have.
   */
  variant?: "default" | "icon" | "primary";
  /**
   * Layout of the default (pill) variant. `"row"` keeps the icon and
   * "Share" label side-by-side (the standard full-width mount). `"stack"`
   * centers a small icon over a tiny label so the button fits a tight
   * multi-column action grid (e.g. the My Posts Boost/Edit/Share/Cancel
   * row at 375px). Ignored by the icon-only variant.
   */
  layout?: "row" | "stack";
  /**
   * Icon variant only: strip the glass chip — no fill, border, or shadow,
   * just the glyph in a 44px tap target. For chrome positions (beside a
   * dialog's own bare X) where a filled tile reads as content.
   */
  bare?: boolean;
  /** `bare` icon variant only: shrinks below the 44px HIG floor (owner,
   *  2026-08-30 — a corner icon row this small forced too much clearance
   *  above the title below it). Needs an inline min-height/min-width
   *  override since the global `button { min-height: 44px }` rule beats a
   *  Tailwind size utility otherwise. */
  compact?: boolean;
  /** Optional aria-label override for the icon-only variant. */
  ariaLabel?: string;
  /**
   * Inline style passthrough for the default (pill) variant so a host
   * row can recolor the button (e.g. the muted-blue Share in the My
   * Posts action grid) without the component baking a single tint in.
   * Ignored by the icon-only variant, which owns its glass-chip look.
   */
  style?: React.CSSProperties;
}

/**
 * Share a job to whoever the user wants — neighbor, friend, social.
 *
 * The tiered fallback chain (Capacitor native sheet → `navigator.share` →
 * clipboard → surface the raw link) lives in `shareNative`
 * (`src/lib/nativeShare.ts`). This component used to carry its OWN copy of
 * that ladder, calling `Capacitor.isNativePlatform()` and `Share.share`
 * directly, which meant two independent implementations of one behaviour and
 * neither picking up the other's fixes — `nativeShare` making `url` optional
 * (the structural cause of the Work Record "shared the homepage" bug) never
 * reached this file, and this file's discovery that confirmation toasts are
 * suppressed never reached `nativeShare`. Both now go through one function.
 *
 * `shareNative` returns a `ShareOutcome` precisely so this button can keep its
 * inline confirmation — see below — instead of that being the reason to keep a
 * duplicate ladder.
 *
 * WHY THE CONFIRMATION IS INLINE AND NOT A TOAST
 * ----------------------------------------------
 * The clipboard rung used to confirm with `toast.success("Link copied…")`.
 * `src/lib/toastPolicy.ts` neuters `toast.success` / `.info` / `.message`
 * app-wide at boot (owner decision: confirmations don't surface), so that call
 * was a guaranteed no-op: the URL landed on the clipboard and NOTHING on
 * screen changed. That is precisely the reported "share button does nothing" —
 * the share worked, the feedback didn't. The confirmation is therefore owned by
 * the button itself (icon + label flip to "Copied" for 2s, plus an sr-only live
 * region), which cannot be suppressed by the toast policy. Because the button
 * owns that confirmation it passes `suppressCopyConfirmation` so `shareNative`
 * does not announce the same copy a second time. Failure reporting is NOT
 * suppressed — `shareNative` still raises `toast.error`, a channel the policy
 * leaves alive, and the "surfaced" tier still shows the link itself.
 *
 * The URL points at the public `/jobs/:id` preview route. Guests who tap
 * get a read-only job preview (apply gated to /signup); signed-in
 * recipients are redirected into the dashboard apply flow. See
 * `src/pages/JobDetail.tsx`.
 */
export function ShareJobButton({
  job,
  className,
  variant = "default",
  layout = "row",
  ariaLabel,
  style,
  bare = false,
  compact = false,
}: ShareJobButtonProps) {
  // Disable the button while a share is in flight so impatient
  // double-taps don't queue duplicate share sheets.
  const [sharing, setSharing] = useState(false);
  // Inline "Copied" confirmation for the clipboard rungs — see the note above
  // on why this cannot be a toast.
  const [copied, setCopied] = useState(false);
  const copiedTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(
    () => () => {
      if (copiedTimer.current) clearTimeout(copiedTimer.current);
    },
    [],
  );

  /**
   * Will this device open a share sheet, or just copy?
   *
   * `navigator.share` does not exist in desktop Safari or in Chrome on macOS,
   * so on a computer the button ALWAYS falls through to the clipboard — and a
   * control labelled "Share" that answers with "Copied" reads as the wrong
   * thing having happened (owner: "I don't understand why it says copied when
   * it's clicked"). Nothing about the behaviour changes; the label just stops
   * promising a sheet the browser cannot open.
   *
   * `isNativePlatform` MUST be part of this test. It used to check only
   * `navigator.share`, which the iOS WKWebView does not reliably expose — the
   * whole reason `@capacitor/share` exists. So inside the shipped app the
   * button rendered "Copy link", then opened the real OS share sheet anyway:
   * the label contradicted the behaviour on the app's primary platform. On
   * native the Capacitor bridge is always the branch that runs, so the sheet
   * is guaranteed regardless of what the WebView advertises.
   *
   * Read once at mount rather than per render: it cannot change for the life
   * of the page, and calling it in render would make the label depend on
   * whether a re-render happened to run before hydration finished.
   */
  const [canNativeShare] = useState(
    () =>
      isNativePlatform ||
      (typeof navigator !== "undefined" && typeof navigator.share === "function"),
  );
  const restLabel = canNativeShare ? "Share" : "Copy link";

  const confirmCopied = () => {
    setCopied(true);
    if (copiedTimer.current) clearTimeout(copiedTimer.current);
    copiedTimer.current = setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (sharing) return;
    setSharing(true);
    // Light haptic on press — confirms the tap on native, no-ops on web.
    void hapticLight();
    const location = job.city || "Louisiana";
    // Append ?ref=share so recipients who tap the link are attributed to
    // the share surface (OS Share Sheet / clipboard) when they open the job.
    const url = `https://www.louisianahelpr.com/jobs/${job.id}?ref=share`;
    const title = `${job.title} — Need help in ${location}`;
    // Every job now has a set budget — bidding (and its "Open to bids" share
    // wording) was removed after zero production usage.
    const priceLabel = `$${job.budget != null ? job.budget : "?"}`;
    const text = `${job.title} · ${priceLabel} · ${location}\n\nApply on Helpr:`;
    const clipText = `${text}\n${url}`;

    try {
      // One ladder, shared with every other share surface in the app.
      // `shareNative` owns the platform branching, the cancellation test, the
      // clipboard recovery after a failed sheet, and the error toast.
      const outcome = await shareNative({
        title,
        text,
        url,
        dialogTitle: "Share this job",
        clipboardText: clipText,
        // This button confirms a copy on itself; without this it would ALSO
        // get shareNative's "Link copied" toast for the same one copy.
        suppressCopyConfirmation: true,
      });
      // Only "copied" gets the inline flip. "shared" means the OS sheet took
      // it (the sheet is its own confirmation), "cancelled" must stay silent,
      // and "surfaced"/"failed" have already put something on screen — a
      // "Copied" badge on either of those would be a lie about where the link
      // ended up, which is the class of bug this file keeps re-learning.
      if (outcome === "copied") confirmCopied();
    } finally {
      setSharing(false);
    }
  };

  /** sr-only live region so the copy is announced, not just drawn. */
  const liveRegion = (
    <span className="sr-only" role="status" aria-live="polite">
      {copied ? "Link copied to clipboard" : ""}
    </span>
  );

  if (variant === "icon") {
    return (
      /**
       * The icon variant has NO LABEL to flip, so the inline confirmation the
       * default variant relies on came down to a 16px glyph swapping for two
       * seconds — which is why the owner reported this one as "does nothing"
       * even after the toast fix. It gets a real, readable confirmation: a
       * chip that floats ABOVE the button, absolutely positioned so the footer
       * row never reflows, and it says which of the two things happened.
       *
       * `pointer-events-none` so the chip can never eat the next click, and it
       * is `aria-hidden` because {@link liveRegion} already announces this to a
       * screen reader — two announcements of one event is worse than none.
       */
      <span className="relative inline-flex shrink-0">
      {copied && (
        <span
          aria-hidden
          className="pointer-events-none absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 whitespace-nowrap rounded-ds-sm px-2 py-1 text-ds-10 font-sans font-semibold"
          style={{
            background: "hsl(var(--ink-deep) / 0.92)",
            color: "hsl(var(--parchment))",
            boxShadow: "0 6px 16px -6px hsl(var(--ink-deep) / 0.45)",
          }}
        >
          {canNativeShare ? "Shared" : "Link copied"}
        </span>
      )}
      <Button
        type="button"
        variant="ghost"
        size="icon"
        aria-label={
        copied
          ? "Link copied to clipboard"
          : (ariaLabel ?? (canNativeShare ? "Share this job" : "Copy a link to this job"))
      }
        disabled={sharing}
        onClick={handleShare}
        className={cn(
          bare
            ? `group rounded-md ${compact ? "h-8 w-8" : "h-11 w-11"} shrink-0 btn-press motion-safe:transition-colors hover:text-foreground hover:bg-transparent active:bg-transparent`
            : "group glass-press rounded-full h-11 w-11 sm:h-12 sm:w-12 shrink-0 motion-safe:transition-all motion-safe:duration-200 motion-safe:hover:scale-105 motion-safe:active:scale-95",
          className,
        )}
        style={bare ? {
          color: "hsl(var(--muted-foreground))",
          ...(compact ? { minHeight: "32px", minWidth: "32px" } : {}),
        } : {
          backgroundColor: "hsla(0, 0%, 100%, 0.32)",
          backdropFilter: "blur(20px) saturate(150%)",
          WebkitBackdropFilter: "blur(20px) saturate(150%)",
          border: "0.5px solid hsla(0, 0%, 100%, 0.4)",
          color: "hsl(var(--olivewood) / 0.80)",
          boxShadow:
            "inset 0 1px 1px 0 rgba(255, 255, 255, 0.4), 0 1px 2px hsl(var(--olivewood) / 0.04)",
          // Transition is handled by motion-safe:transition-all in className
        }}
      >
        {copied ? (
          <Check className="w-4 h-4" strokeWidth={2.5} />
        ) : (
          <Share2 className="w-4 h-4 motion-safe:transition-transform motion-safe:duration-300 motion-safe:group-hover:-translate-y-0.5" />
        )}
        {liveRegion}
      </Button>
      </span>
    );
  }

  if (variant === "primary") {
    return (
      <BarkPillButton
        type="button"
        aria-label={copied ? "Link copied to clipboard" : (ariaLabel ?? "Share this job")}
        disabled={sharing}
        onClick={handleShare}
        className={cn("w-full max-w-xs", className)}
        style={style}
      >
        {copied ? (
          <Check className="w-4 h-4 mr-1.5" strokeWidth={2.5} />
        ) : (
          <Share2 className="w-4 h-4 mr-1.5" />
        )}
        {copied ? "Copied" : restLabel}
        {liveRegion}
      </BarkPillButton>
    );
  }

  return (
    <Button
      type="button"
      size="sm"
      // The default variant pins its text to parchment-cream with
      // `!important`, which an inline `style.color` can't beat. When a host
      // recolors via `style`, drop to the ghost variant (no forced text) so
      // the override actually renders; the no-style mount keeps `default`.
      variant={style ? "ghost" : "default"}
      aria-label={copied ? "Link copied to clipboard" : (ariaLabel ?? "Share this job")}
      disabled={sharing}
      onClick={handleShare}
      style={style}
      className={cn(
        "border-0",
        // Default tint: neutral parchment-green via the bark token. When
        // the host passes an inline `style` (e.g. the muted-blue Share in
        // My Posts) the green is dropped so the override wins cleanly,
        // including on hover.
        !style && "bg-[hsl(var(--bark)/0.10)] text-[hsl(var(--bark))] hover:bg-[hsl(var(--bark)/0.20)]",
        className,
      )}
    >
      {layout === "stack" ? (
        <>
          {copied ? <Check className="w-4 h-4" strokeWidth={2.5} /> : <Share2 className="w-4 h-4" />}
          {/* The flip is label→confirmation, and both stay short enough that
              the 4-up action grid does not reflow. */}
          <span className="text-ds-11 leading-none font-medium">
            {copied ? "Copied" : restLabel}
          </span>
        </>
      ) : (
        <>
          {copied ? (
            <Check className="w-4 h-4 mr-1" strokeWidth={2.5} />
          ) : (
            <Share2 className="w-4 h-4 mr-1" />
          )}
          {copied ? "Copied" : restLabel}
        </>
      )}
      {liveRegion}
    </Button>
  );
}
